using System.Net;
using System.Net.Http.Json;
using CondoManager.Application;
using CondoManager.Domain;
using CondoManager.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Npgsql;
namespace CondoManager.IntegrationTests;
[Collection("PostgreSQL")]
public class MeetingTests
{
 private sealed record Context(Guid? TenantId):ICurrentTenant{public Guid? UserId=>TenantId;public StudioRole? Role=>StudioRole.StudioAdmin;}
 private static AppDbContext Db(Guid? tenant=null)=>new(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(Environment.GetEnvironmentVariable("CONDOMANAGER_TEST_POSTGRES")).Options,new Context(tenant));
 private static async Task<T> Send<T>(HttpClient c,string path,object body,string method="POST"){using var r=await c.SendAsync(new(new HttpMethod(method),path){Content=JsonContent.Create(body,options:SecurityTestHost.Json)});Assert.True(r.IsSuccessStatusCode,$"{path}: {r.StatusCode}: {await r.Content.ReadAsStringAsync()}");return(await r.Content.ReadFromJsonAsync<T>(SecurityTestHost.Json))!;}
 private static async Task<HttpStatusCode> Status(HttpClient c,string path,object body){using var r=await c.PostAsJsonAsync(path,body,SecurityTestHost.Json);return r.StatusCode;}
 private static MeetingInput Input(Guid? period=null,MeetingType type=MeetingType.Ordinary)=>new(0,"Synthetic meeting",type,period,"Synthetic room",null,null,new DateTimeOffset(2026,12,10,6,0,0,TimeSpan.Zero),new DateTimeOffset(2026,12,11,19,30,0,TimeSpan.Zero));
 internal sealed class Fixture(ResidentFinanceTests.Fixture data,MeetingDetails details,Guid table):IAsyncDisposable
 {
  public ResidentFinanceTests.Fixture Data=>data;public HttpClient C=>data.C;public MeetingDetails D=details;public Guid Table=>table;public string Base=>"/api/meetings/condominiums/"+data.Base.Condo;public string Path=>Base+"/"+D.Meeting.Id;public int V=>D.Meeting.Version;
  public async Task Change(string suffix,object body){D=await Send<MeetingDetails>(C,Path+suffix,body);}
  public ParticipantsInput Participants(DateOnly? date=null,IReadOnlyList<RepresentativeChoice>? reps=null)=>new(V,date??new(2026,11,1),Table,"Synthetic explicit consolidation",reps??[]);
  public async Task Snapshot(){await Change("/snapshots",Participants());}
  public async Task Convene(){await Change("/agenda",new AgendaInput(V,null,"Synthetic agenda",null,AgendaCategory.General,null,null));await Snapshot();foreach(var p in D.Snapshots.Last().Participants.People)await Change("/notices",new NoticeInput(V,p.Id,NoticeChannel.HandDelivery,"Synthetic contact"));await Change("/status",new MeetingTransition(V,MeetingStatus.Scheduled));await Change("/status",new MeetingTransition(V,MeetingStatus.Convened));}
  public async ValueTask DisposeAsync()=>await data.DisposeAsync();
 }
 internal static async Task<Fixture> Setup(MeetingType type=MeetingType.Ordinary){var f=await ResidentFinanceTests.Setup();await using var db=Db(f.Base.Tenant);var table=await db.AllocationTables.SingleAsync(t=>t.CondominiumId==f.Base.Condo&&t.Code=="T");var d=await Send<MeetingDetails>(f.C,"/api/meetings/condominiums/"+f.Base.Condo,Input(f.Base.Period,type));return new(f,d,table.Id);}
 [PostgresFact]public async Task OrdinaryExtraordinaryDatesAndTwoDistinctCalls(){await using var f=await Setup();Assert.Equal(2,f.D.Meeting.Sessions.Count);Assert.Equal(new[]{MeetingCall.First,MeetingCall.Second},f.D.Meeting.Sessions.Select(s=>s.Call));var extra=await Send<MeetingDetails>(f.C,f.Base,Input(type:MeetingType.Extraordinary));Assert.Equal(MeetingType.Extraordinary,extra.Meeting.Type);Assert.Equal(HttpStatusCode.BadRequest,await Status(f.C,f.Base,Input() with{SecondCallAt=Input().FirstCallAt.AddMinutes(-1)}));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/status",new MeetingTransition(f.V,MeetingStatus.Completed)));using var deactivate=await f.C.DeleteAsync("/api/condominiums/"+f.Data.Base.Condo);deactivate.EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Base,Input()));}
 [PostgresFact]public async Task AgendaReordersAndKeepsBudgetAndFinalVersionReferences(){await using var f=await Setup();await f.Change("/agenda",new AgendaInput(f.V,null,"Budget",null,AgendaCategory.BudgetApproval,MeetingReference.Budget,f.Data.Budget));await f.Change("/agenda",new AgendaInput(f.V,null,"Period",null,AgendaCategory.General,MeetingReference.AccountingPeriod,f.Data.Base.Period));var first=f.D.Meeting.Agenda[0].Id;await f.Change("/agenda/reorder",new AgendaOrder(f.V,f.D.Meeting.Agenda.Reverse().Select(a=>a.Id).ToArray()));Assert.Equal(first,f.D.Meeting.Agenda[1].Id);await f.Change("/agenda/"+first+"/delete",new MeetingVersion(f.V));Assert.Equal(1,Assert.Single(f.D.Meeting.Agenda).Position);
  var finalPath=$"/api/final-statements/condominiums/{f.Data.Base.Condo}";var final=await Send<FinalDto>(f.C,finalPath,new FinalInput(f.Data.Base.Period,"Synthetic final draft",Guid.NewGuid()));await f.Change("/agenda",new AgendaInput(f.V,null,"Final version",null,AgendaCategory.FinalStatementApproval,MeetingReference.FinalStatement,final.Id));Assert.Equal(final.Id,f.D.Meeting.Agenda.Last().RelatedId);Assert.Equal(FinalStatementStatus.Draft,(await f.C.GetFromJsonAsync<FinalDto[]>(finalPath,SecurityTestHost.Json))!.Single().Status);
  var other=await Send<CondominiumDto>(f.C,"/api/condominiums",new CondominiumInput("OTHER","Synthetic other",null,"Street","00000","Test","XX","Test"));var period=await Send<AccountingPeriodDto>(f.C,$"/api/condominiums/{other.Id}/accounting-periods",new AccountingPeriodInput("OTHER","Other period",new(2026,1,1),new(2026,12,31)));Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,f.Path+"/agenda",new AgendaInput(f.V,null,"Wrong",null,AgendaCategory.General,MeetingReference.AccountingPeriod,period.Id)));
 }
 [PostgresFact]public async Task SnapshotOwnsOneUnitShareAndRemainsImmutableAfterRegistryChange(){await using var f=await Setup();var p=await Send<ParticipantsPreview>(f.C,f.Path+"/participants/preview",f.Participants());Assert.Equal(1000,p.Units.Sum(u=>u.Millesimals));Assert.All(p.Units,u=>Assert.NotNull(u.RepresentativeId));await f.Snapshot();var original=f.D.Snapshots.Single();await using var db=Db(f.Data.Base.Tenant);var owner=await db.OwnershipPeriods.SingleAsync(x=>x.PropertyUnitId==f.Data.Units[0]);owner.End(new(2026,11,2));await db.SaveChangesAsync();await Send<AssociationDto>(f.C,$"/api/condominiums/{f.Data.Base.Condo}/units/{f.Data.Units[0]}/associations",new AssociationInput(f.Data.People[1],UnitPersonRole.Owner,new(2026,11,3),null,1));var changed=await Send<ParticipantsPreview>(f.C,f.Path+"/participants/preview",f.Participants(new(2026,11,4)));Assert.NotEqual(original.Participants.Fingerprint,changed.Fingerprint);await f.Change("/snapshots",f.Participants(new(2026,11,4)));Assert.Equal(2,f.D.Snapshots.Count);Assert.Equal(f.Data.People[0],f.D.Snapshots[0].Participants.Units.Single(u=>u.Id==f.Data.Units[0]).RepresentativeId);Assert.Equal(f.Data.People[1],f.D.Snapshots[1].Participants.Units.Single(u=>u.Id==f.Data.Units[0]).RepresentativeId);await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"MeetingSnapshots\" SET \"Reason\"={"tamper"} WHERE \"Id\"={original.Id}"));}
 [PostgresFact]public async Task CoOwnershipNeedsExplicitUnitRepresentativeWithoutDuplicatingMillesimals(){await using var f=await Setup();await using var db=Db(f.Data.Base.Tenant);var owner=await db.OwnershipPeriods.SingleAsync(x=>x.PropertyUnitId==f.Data.Units[0]);owner.End(new(2026,6,30));await db.SaveChangesAsync();foreach(var person in f.Data.People.Take(2))await Send<AssociationDto>(f.C,$"/api/condominiums/{f.Data.Base.Condo}/units/{f.Data.Units[0]}/associations",new AssociationInput(person,UnitPersonRole.CoOwner,new(2026,7,1),null,.5m));var p=await Send<ParticipantsPreview>(f.C,f.Path+"/participants/preview",f.Participants());var unit=p.Units.Single(x=>x.Id==f.Data.Units[0]);Assert.Null(unit.RepresentativeId);Assert.Equal(2,unit.Holdings.Count);Assert.Equal(500,unit.Millesimals);Assert.Equal(1000,p.Units.Sum(x=>x.Millesimals));Assert.Contains(unit.Anomalies,a=>a.Contains("Rappresentanza"));await f.Change("/snapshots",f.Participants(reps:[new(unit.Id,f.Data.People[0])]));Assert.Equal(f.Data.People[0],f.D.Snapshots.Last().Participants.Units.Single(x=>x.Id==unit.Id).RepresentativeId);}
 [PostgresFact]public async Task ManualNoticeEventsAreDeclarationsAndKeepContactSnapshot(){await using var f=await Setup();await f.Snapshot();await f.Change("/notices",new NoticeInput(f.V,f.Data.People[0],NoticeChannel.Email,"synthetic@test.invalid"));var n=f.D.Notices.Single();Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/notices/{n.Id}/status",new NoticeTransition(f.V,NoticeStatus.Delivered,DateTimeOffset.UtcNow,null,null)));foreach(var state in new[]{NoticeStatus.Ready,NoticeStatus.Sent,NoticeStatus.Delivered})await f.Change($"/notices/{n.Id}/status",new NoticeTransition(f.V,state,DateTimeOffset.UtcNow,"Synthetic declaration",null));n=f.D.Notices.Single();Assert.Equal(3,n.Events.Count);Assert.All(n.Events,e=>Assert.False(e.VerifiedEvidence));Assert.Equal("synthetic@test.invalid",n.Contact);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/notices",new NoticeInput(f.V,f.Data.People[0],NoticeChannel.Email,"other@test.invalid")));}
 [PostgresFact]public async Task ProxyVerifiedAttendanceRejectsDuplicatesAndKeepsIndependentCalls(){await using var f=await Setup();await f.Convene();var first=f.D.Meeting.Sessions.Single(s=>s.Call==MeetingCall.First);var second=f.D.Meeting.Sessions.Single(s=>s.Call==MeetingCall.Second);await f.Change("/proxies",new ProxyInput(f.V,f.Data.People[0],f.Data.People[1],[f.Data.Units[0]],DateTimeOffset.UtcNow,null,"Synthetic document"));var proxy=f.D.Proxies.Single();Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/proxies",new ProxyInput(f.V,f.Data.People[0],f.Data.People[2],[f.Data.Units[0]],DateTimeOffset.UtcNow,null,null)));await f.Change($"/sessions/{first.Id}",new SessionTransition(f.V,SessionStatus.InProgress));var input=new AttendanceInput(f.V,first.Id,f.Data.People[0],AttendanceType.ByProxy,proxy.Id,[f.Data.Units[0]],DateTimeOffset.UtcNow,null);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/attendances",input));await f.Change($"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Submitted));await f.Change($"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Verified));await f.Change("/attendances",input with{ExpectedVersion=f.V});Assert.Equal(500,f.D.Attendances.Single().Millesimals);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/attendances",input with{ExpectedVersion=f.V}));var a=f.D.Attendances.Single();await f.Change($"/attendances/{a.Id}/exit",new AttendanceExit(f.V,DateTimeOffset.UtcNow));await f.Change($"/sessions/{first.Id}",new SessionTransition(f.V,SessionStatus.Ended));await f.Change($"/sessions/{second.Id}",new SessionTransition(f.V,SessionStatus.InProgress));await f.Change("/attendances",input with{ExpectedVersion=f.V,SessionId=second.Id,CheckInAt=DateTimeOffset.UtcNow});Assert.Equal(2,f.D.Attendances.Count);Assert.NotEqual(f.D.Attendances[0].SessionId,f.D.Attendances[1].SessionId);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Revoked)));await f.Change($"/attendances/{f.D.Attendances.Last().Id}/exit",new AttendanceExit(f.V,DateTimeOffset.UtcNow));await f.Change($"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Revoked));Assert.Equal(ProxyStatus.Revoked,f.D.Proxies.Single().Status);await f.Change("/attendances",input with{ExpectedVersion=f.V,SessionId=second.Id,Type=AttendanceType.InPerson,ProxyId=null,CheckInAt=DateTimeOffset.UtcNow});Assert.Equal(3,f.D.Attendances.Count);}
 [PostgresFact]public async Task DirectAttendanceAbsenceAndSecondCallNotAutomatic(){await using var f=await Setup();await f.Convene();var first=f.D.Meeting.Sessions.First();var second=f.D.Meeting.Sessions.Last();Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+$"/sessions/{second.Id}",new SessionTransition(f.V,SessionStatus.InProgress)));await f.Change($"/sessions/{first.Id}",new SessionTransition(f.V,SessionStatus.NotHeld));await f.Change("/absences",new AbsenceInput(f.V,first.Id,f.Data.People[0],"Declared absent"));await f.Change($"/sessions/{second.Id}",new SessionTransition(f.V,SessionStatus.InProgress));await f.Change("/attendances",new AttendanceInput(f.V,second.Id,f.Data.People[0],AttendanceType.InPerson,null,[f.Data.Units[0]],DateTimeOffset.UtcNow,null));Assert.Single(f.D.Absences);Assert.Single(f.D.Attendances);Assert.Equal(SessionStatus.NotHeld,f.D.Meeting.Sessions.First().Status);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,f.Path+"/agenda",new AgendaInput(f.V,null,"Too late",null,AgendaCategory.General,null,null)));}
 [PostgresFact]public async Task ConcurrentVersionAuditRolesCsrfAndCrossScope(){await using var f=await Setup();var input=new AgendaInput(f.V,null,"Race",null,AgendaCategory.General,null,null);var statuses=await Task.WhenAll(Status(f.C,f.Path+"/agenda",input),Status(f.C,f.Path+"/agenda",input));Assert.Single(statuses,s=>s==HttpStatusCode.OK);Assert.Single(statuses,s=>s==HttpStatusCode.Conflict);f.D=(await f.C.GetFromJsonAsync<MeetingDetails>(f.Path,SecurityTestHost.Json))!;await f.Snapshot();var history=(await f.C.GetFromJsonAsync<MeetingHistoryDto[]>(f.Path+"/history",SecurityTestHost.Json))!;Assert.Equal(f.V,history.Length);await using(var db=Db(f.Data.Base.Tenant))Assert.True(await db.SecurityAudits.AnyAsync(x=>x.SubjectId==f.D.Meeting.Id&&x.Event=="Meeting.ParticipantsConsolidated"));
  using var viewer=f.Data.Base.Host.Browser();await SecurityTestHost.Login(viewer,await f.Data.Base.Host.Account(f.Data.Base.Tenant,StudioRole.Viewer),f.Data.Base.Tenant);Assert.Equal(HttpStatusCode.Forbidden,await Status(viewer,f.Path+"/agenda",new AgendaInput(f.V,null,"No",null,AgendaCategory.General,null,null)));var redacted=(await viewer.GetFromJsonAsync<MeetingDetails>(f.Path,SecurityTestHost.Json))!;Assert.Empty(redacted.Notices);Assert.All(redacted.Snapshots.SelectMany(s=>s.Participants.People),p=>{Assert.Null(p.Email);Assert.Null(p.MailingAddress);});Assert.Equal(HttpStatusCode.Forbidden,(await viewer.GetAsync(f.Path+"/history")).StatusCode);
  await f.Change("/proxies",new ProxyInput(f.V,f.Data.People[0],f.Data.People[1],[f.Data.Units[0]],DateTimeOffset.UtcNow,null,null));var proxy=f.D.Proxies.Single();await f.Change($"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Submitted));using var collaborator=f.Data.Base.Host.Browser();await SecurityTestHost.Login(collaborator,await f.Data.Base.Host.Account(f.Data.Base.Tenant,StudioRole.Collaborator),f.Data.Base.Tenant);Assert.Equal(HttpStatusCode.Forbidden,await Status(collaborator,f.Path+$"/proxies/{proxy.Id}/status",new ProxyTransition(f.V,ProxyStatus.Verified)));
  using var noCsrf=f.Data.Base.Host.Browser();await SecurityTestHost.Login(noCsrf,await f.Data.Base.Host.Account(f.Data.Base.Tenant),f.Data.Base.Tenant);noCsrf.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");Assert.Equal(HttpStatusCode.BadRequest,await Status(noCsrf,f.Path+"/status",new MeetingTransition(f.V,MeetingStatus.Scheduled)));
  await using var other=await Setup();Assert.Equal(HttpStatusCode.NotFound,(await other.C.GetAsync(f.Path)).StatusCode);var condo=await Send<CondominiumDto>(f.C,"/api/condominiums",new CondominiumInput("C2","Other synthetic",null,"Street","00000","Test","XX","Test"));Assert.Equal(HttpStatusCode.NotFound,(await f.C.GetAsync($"/api/meetings/condominiums/{condo.Id}/{f.D.Meeting.Id}")).StatusCode);
 }
}
